-- Airport polygons: OpenStreetMap contributors, ODbL 1.0, https://www.openstreetmap.org/copyright
-- Edward approved regions and 13 new directional fares, 2026-10-16.
-- Apply only this file after reviewed backup/prechecks; no existing fare is altered.
-- Existing routes/vehicle_prices are the single fare source; no existing price is changed.
CREATE TABLE pricing_regions (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
 code VARCHAR(30) NOT NULL UNIQUE,
 fare_location_code VARCHAR(30) NOT NULL,
 airport_iata CHAR(3) NULL UNIQUE,
 geometry JSON NOT NULL,
 priority SMALLINT UNSIGNED NOT NULL DEFAULT 10,
 is_active TINYINT(1) NOT NULL DEFAULT 1,
 source TEXT NOT NULL,
 updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- Separate regional additions preserve legacy calculation and the landing catalog.
-- Switching REGION_FIXED_FARES_ENABLED=false immediately ignores this table.
CREATE TABLE pricing_region_fares (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
 origin_code VARCHAR(30) NOT NULL, destination_code VARCHAR(30) NOT NULL,
 vehicle_code VARCHAR(30) NOT NULL,
 price DECIMAL(12,2) NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'THB',
 is_active TINYINT(1) NOT NULL DEFAULT 1,
 updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE KEY regional_pair_vehicle(origin_code,destination_code,vehicle_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
